public sealed class LogReader { public (List<LogEvent> Events,List<string> Errors) Read(string input){ var ev=new List<LogEvent>(); var er=new List<string>(); if(File.Exists(input)){ReadFile(input,ev,er);} else if(Directory.Exists(input)){foreach(var f in Directory.EnumerateFiles(input,"*.*",SearchOption.AllDirectories).Where(f=>f.EndsWith(".jsonl")||f.EndsWith(".csv")||f.EndsWith(".zip"))) ReadFile(f,ev,er);} else er.Add($"Input not found: {input}"); return (ev.OrderBy(e=>e.TimestampUtc).ToList(),er);} void ReadFile(string f,List<LogEvent> ev,List<string> er){try{ if(f.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)){ using var z=ZipFile.OpenRead(f); foreach(var e in z.Entries.Where(x=>x.FullName.EndsWith(".jsonl")||x.FullName.EndsWith(".csv"))){ using var r=new StreamReader(e.Open()); ReadLines(e.FullName,r.ReadToEnd().Split('\n'),ev,er); }} else ReadLines(f,File.ReadLines(f),ev,er);}catch(Exception ex){er.Add($"{f}: {ex.Message}");}} void ReadLines(string source,IEnumerable<string> lines,List<LogEvent> ev,List<string> er){var arr=lines.Where(l=>!string.IsNullOrWhiteSpace(l)).ToArray(); if(source.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)) ReadCsv(source,arr,ev,er); else foreach(var l in arr){try{ev.Add(ParseJson(l,source));}catch(Exception ex){er.Add($"{source}: bad JSONL row: {ex.Message}");}}} LogEvent ParseJson(string line,string source){using var d=JsonDocument.Parse(line); var r=d.RootElement; string S(string n)=>r.TryGetProperty(n,out var v)?v.GetString()??"":""; double? D(string n)=>r.TryGetProperty(n,out var v)&&v.TryGetDouble(out var x)?x:null; int I(string n)=>r.TryGetProperty(n,out var v)&&v.TryGetInt32(out var x)?x:0; bool B(string n)=>r.TryGetProperty(n,out var v)&&v.ValueKind==JsonValueKind.True; var ts=DateTimeOffset.Parse(S("timestampUtc"),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal); return new(S("eventType") is {Length:>0} et?et:"activity",ts, DateTimeOffset.TryParse(S("timestampLocal"),out var tl)?tl:ts.ToLocalTime(